/**
 * Informes: generación en pantalla + exportación a PDF (jsPDF), Excel
 * (SheetJS) y envío por correo (mailto). Incluye ahora el estado de pago
 * de cada registro de horas (pagado / pendiente de cobro), para que el
 * informe muestre no solo el valor ejecutado sino también lo que queda
 * pendiente de pago (cuentas por cobrar).
 */
let lastReport = null;

// Logo en base64 para el encabezado del PDF (mismo isotipo de la barra superior).
const REPORT_LOGO_B64 = 'data:image/png;base64,';

function generateReport() {
  try {
    const c = company(), s = site();
    if (!c || !s) { toast('Selecciona empresa y sede antes de generar el informe.'); return null; }
    const m = $('reportMonth')?.value || selectedMonth(), scope = $('reportScope')?.value || 'monthly';
    const monthly = state.hoursSite.filter(x => x.site_id === s.id && monthOf(x.record_date) === m);
    const all = state.hoursSite.filter(x => x.site_id === s.id);
    const rows = scope === 'global' ? all : monthly;

    const used = rows.reduce((a, x) => a + Number(x.hours), 0);
    const executed = rows.reduce((a, x) => a + Number(x.hours) * Number(x.rate), 0);
    const paidValue = rows.filter(x => x.paid).reduce((a, x) => a + Number(x.hours) * Number(x.rate), 0);
    const owedValue = rows.filter(x => !x.paid).reduce((a, x) => a + Number(x.hours) * Number(x.rate), 0);
    const paidCount = rows.filter(x => x.paid).length, owedCount = rows.length - paidCount;
    const monthValue = monthly.reduce((a, x) => a + Number(x.hours) * Number(x.rate), 0);

    const bag = state.bag, bagRemainingValue = bag.remaining * Number(state.rate || 0);
    const ev = state.evidencesSite.filter(x => scope === 'global' || monthOf(x.record_date) === m);
    const acts = state.activities.map((t, i) => {
      const st = taskStatus(s.id, t.id), hrs = scope === 'global' ? taskHours(s.id, t.id) : taskMonthHours(s.id, t.id, m);
      const target = activityTarget(s.id, t.id);
      return { name: t.name, status: st, hours: hrs, target, icon: actIcon(i) };
    });
    const title = scope === 'global' ? 'Informe global consolidado SG-SST' : 'Informe mensual de seguimiento SG-SST';
    const genDate = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

    $('reportBox').innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px">
      <div><h2 style="margin:0 0 4px">${title}</h2><p class="small" style="margin:0">Generado el ${genDate}</p></div>
    </div>
    <p style="margin-top:14px"><b>Empresa:</b> ${c.name}<br><b>Sede:</b> ${s.name}<br><b>Mes de referencia:</b> ${m}${scope === 'global' ? '<br><span class="small">El consolidado incluye todos los registros históricos de la sede.</span>' : ''}</p>

    <h3>💰 Valores y cobros</h3>
    <div class="kpirow">
      <div class="kpi"><span class="small">Horas ${scope === 'global' ? 'totales' : 'del mes'}</span><b>${used} h</b></div>
      <div class="kpi"><span class="small">Saldo pendiente de pago</span><b style="color:var(--red)">${money(owedValue)}</b><span class="small">${owedCount} de ${rows.length} registro(s) · ejecutado ${money(executed)} · pagado ${money(paidValue)}</span></div>
    </div>

    <h3 style="margin-top:18px">🗂️ Bolsa de horas de ${m}</h3>
    <div class="kpirow">
      <div class="kpi"><span class="small">Bolsa del mes (total)</span><b>${bag.total} h</b><span class="small">Asignadas ${bag.assigned} · Saldo ${bag.carry} · Adicionales ${bag.additional}</span></div>
      <div class="kpi"><span class="small">Horas ejecutadas en ${m}</span><b>${bag.used} h</b></div>
      <div class="kpi"><span class="small">Saldo disponible (valorizado)</span><b>${bag.remaining} h</b><span class="small">${money(bagRemainingValue)} en horas aún no ejecutadas</span></div>
    </div>

    <h3 style="margin-top:18px">📋 Actividades</h3>
    <ol>${acts.map(a => `<li>${a.icon} <b>${a.name}</b> — ${a.status} · ${a.hours} h registradas${a.target ? ` · meta ${a.target} h (${Math.min(100, Math.round(100 * a.hours / a.target))}%)` : ''}</li>`).join('')}</ol>

    <h3>📎 Evidencias registradas (${ev.length})</h3>
    ${ev.length ? `<ul>${ev.slice(0, 12).map(x => `<li>${x.record_date} · ${taskName(x.activity_id)}${x.description ? ' — ' + x.description : ''}${x.link ? ` — <a class="link" href="${safeUrl(x.link)}" target="_blank">🔗 ver enlace</a>` : ''}${x.storage_path ? ` — <a class="link" href="#" onclick="openEvidenceFile('${x.id}');return false">📄 ${x.file_name || 'archivo'}</a>` : ''}</li>`).join('')}</ul>${ev.length > 12 ? `<p class="small">y ${ev.length - 12} evidencia(s) más…</p>` : ''}` : '<p class="small">No hay evidencias registradas en este periodo.</p>'}

    <h3>🧾 Detalle de horas ejecutadas</h3>
    <div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Actividad</th><th>Horas</th><th>Tarifa</th><th>Valor</th><th>Pago</th></tr></thead><tbody>
      ${rows.length ? [...rows].sort((a, b) => b.record_date.localeCompare(a.record_date)).map(x => `<tr><td>${x.record_date}</td><td>${taskName(x.activity_id)}</td><td>${x.hours}</td><td>${money(x.rate)}</td><td>${money(x.hours * x.rate)}</td><td><span class="badge ${x.paid ? 'paid' : 'unpaid'}">${x.paid ? '✓ Pagado' : '⏳ Pendiente'}</span></td></tr>`).join('') : '<tr><td colspan="6" class="empty">Sin registros en este periodo.</td></tr>'}
    </tbody></table></div>

    <h3 style="margin-top:18px">📐 Regla operativa de la bolsa</h3>
    <p class="small">Las horas asignadas normalmente se registran durante los primeros 5 días del mes. Si quedan horas sin ejecutar, el saldo se traslada automáticamente al siguiente mes como saldo a favor. Las ampliaciones quedan registradas como adicionales del mes correspondiente.</p>
    <p class="small" style="margin-top:18px;border-top:1px dashed var(--line);padding-top:10px">Elaborado por Yasbleidis López Rhenals · Fisioterapeuta, Especialista en Gerencia de la Seguridad y Salud en el Trabajo.</p>
    `;
    toast('Informe generado');
    lastReport = { c, s, m, scope, used, executed, paidValue, owedValue, paidCount, owedCount, monthValue, bagRemainingValue, ev, bag, acts, rows, title, genDate };
    return lastReport;
  } catch (err) {
    console.error('Error generando el informe:', err);
    toast('No se pudo generar el informe: ' + (err?.message || err));
    return null;
  }
}

function prepareEmail() {
  const r = lastReport || generateReport();
  if (!r) return;
  const subject = encodeURIComponent(`Informe ${r.scope === 'global' ? 'global' : 'mensual'} SG-SST – ${r.s.name} – ${r.m}`);
  const body = encodeURIComponent(
    `Cordial saludo,\n\n` +
    `Compartimos el informe ${r.scope === 'global' ? 'global consolidado' : 'mensual'} de seguimiento para ${r.c.name}, sede ${r.s.name}.\n\n` +
    `Horas ${r.scope === 'global' ? 'totales' : 'del mes'}: ${r.used} h\n` +
    `Valor ejecutado: ${money(r.executed)}\n` +
    `Valor pagado: ${money(r.paidValue)} (${r.paidCount} registro(s))\n` +
    `Valor pendiente por cobrar: ${money(r.owedValue)} (${r.owedCount} registro(s))\n` +
    `Saldo disponible en bolsa de ${r.m}: ${r.bag.remaining} h\n\n` +
    `Adjunto el informe completo en PDF/Excel exportado desde la plataforma.\n\n` +
    `Cordialmente,\nYasbleidis López Rhenals`
  );
  window.location.href = `mailto:?subject=${subject}&body=${body}`;
}

function exportReportPDF() {
  const r = lastReport || generateReport();
  if (!r) return;
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();
  try { doc.addImage(REPORT_LOGO_B64, 'PNG', 14, 10, 46, 20); } catch (e) { /* si falla el logo, se sigue sin él */ }
  doc.setFontSize(15); doc.text(r.title, 66, 20);
  doc.setFontSize(9); doc.setTextColor(100);
  doc.text(`Generado el ${r.genDate}`, 66, 26);
  doc.setTextColor(20);
  doc.setFontSize(10);
  doc.text(`Empresa: ${r.c.name}`, 14, 40);
  doc.text(`Sede: ${r.s.name}`, 14, 46);
  doc.text(`Mes de referencia: ${r.m}`, 14, 52);

  doc.autoTable({
    startY: 58,
    head: [['Indicador', 'Valor']],
    body: [
      ['Horas', `${r.used} h`],
      ['Valor ejecutado', money(r.executed)],
      ['Valor pagado', `${money(r.paidValue)} (${r.paidCount} registro(s))`],
      ['Valor pendiente por cobrar', `${money(r.owedValue)} (${r.owedCount} registro(s))`],
      ['Valor del mes', money(r.monthValue)],
      ['Bolsa del mes (total)', `${r.bag.total} h`],
      ['Saldo disponible en bolsa', `${r.bag.remaining} h (${money(r.bagRemainingValue)})`],
    ],
    headStyles: { fillColor: [24, 50, 74] },
  });

  doc.autoTable({
    startY: doc.lastAutoTable.finalY + 8,
    head: [['Actividad', 'Estado', 'Horas', 'Meta', '%']],
    body: r.acts.map(a => [a.name, a.status, a.hours, a.target || '—', a.target ? `${Math.min(100, Math.round(100 * a.hours / a.target))}%` : '—']),
    headStyles: { fillColor: [24, 50, 74] },
  });

  doc.autoTable({
    startY: doc.lastAutoTable.finalY + 8,
    head: [['Fecha', 'Actividad', 'Horas', 'Tarifa', 'Valor', 'Pago']],
    body: [...r.rows].sort((a, b) => b.record_date.localeCompare(a.record_date)).map(x => [x.record_date, taskName(x.activity_id), x.hours, money(x.rate), money(x.hours * x.rate), x.paid ? 'Pagado' : 'Pendiente']),
    headStyles: { fillColor: [24, 50, 74] },
    styles: { fontSize: 8 },
  });

  if (r.ev.length) {
    doc.autoTable({
      startY: doc.lastAutoTable.finalY + 8,
      head: [['Fecha', 'Actividad', 'Descripción', 'Enlace / archivo']],
      body: r.ev.map(x => [x.record_date, taskName(x.activity_id), x.description || '-', x.link || x.file_name || '-']),
      headStyles: { fillColor: [24, 50, 74] },
      styles: { fontSize: 8 },
    });
  }

  const finalY = doc.lastAutoTable.finalY + 16;
  doc.setFontSize(9); doc.setTextColor(90);
  doc.text('Elaborado por: Yasbleidis López Rhenals', 14, finalY);
  doc.text('Fisioterapeuta · Especialista en Gerencia de la Seguridad y Salud en el Trabajo', 14, finalY + 5);

  doc.save(`informe-sgsst-${r.s.name.replace(/\s+/g, '_')}-${r.m}.pdf`);
}

function exportReportExcel() {
  const r = lastReport || generateReport();
  if (!r) return;
  const wb = XLSX.utils.book_new();

  const summary = [
    ['Informe', r.title],
    ['Generado el', r.genDate],
    ['Empresa', r.c.name],
    ['Sede', r.s.name],
    ['Mes de referencia', r.m],
    [],
    ['Indicador', 'Valor'],
    ['Horas', r.used],
    ['Valor ejecutado', r.executed],
    ['Valor pagado', r.paidValue],
    ['Valor pendiente por cobrar', r.owedValue],
    ['Valor del mes', r.monthValue],
    ['Bolsa del mes (total)', r.bag.total],
    ['Saldo disponible en bolsa', r.bag.remaining],
    ['Saldo disponible (valorizado)', r.bagRemainingValue],
  ];
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(summary), 'Resumen');

  const actRows = [['Actividad', 'Estado', 'Horas', 'Meta (h)', '% avance']].concat(
    r.acts.map(a => [a.name, a.status, a.hours, a.target || '', a.target ? Math.min(100, Math.round(100 * a.hours / a.target)) : ''])
  );
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(actRows), 'Actividades');

  const detailRows = [['Fecha', 'Actividad', 'Horas', 'Tarifa', 'Valor', 'Pagado']].concat(
    [...r.rows].sort((a, b) => b.record_date.localeCompare(a.record_date)).map(x => [x.record_date, taskName(x.activity_id), x.hours, x.rate, x.hours * x.rate, x.paid ? 'Sí' : 'No'])
  );
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(detailRows), 'Detalle de horas');

  const paymentRows = [['Estado', 'Cantidad de registros', 'Valor']].concat([
    ['Pagado', r.paidCount, r.paidValue],
    ['Pendiente por cobrar', r.owedCount, r.owedValue],
  ]);
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(paymentRows), 'Cobros');

  const evRows = [['Fecha', 'Actividad', 'Descripción', 'Enlace / archivo']].concat(
    r.ev.map(x => [x.record_date, taskName(x.activity_id), x.description || '', x.link || x.file_name || ''])
  );
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(evRows), 'Evidencias');

  XLSX.writeFile(wb, `informe-sgsst-${r.s.name.replace(/\s+/g, '_')}-${r.m}.xlsx`);
}
